.ds-btn {
  --btn-bg: var(--surface);
  --btn-fg: var(--ink);
  --btn-border: var(--line-strong);
  --btn-hover: var(--surface-2);
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 48px;
  padding: 0 20px;
  border: 1.5px solid var(--btn-border);
  border-radius: var(--r-control);
  background: var(--btn-bg);
  color: var(--btn-fg);
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 650;
  line-height: 1.1;
  text-decoration: none;
  white-space: normal;
  text-align: center;
  transition:
    background-color var(--dur) var(--ease),
    border-color var(--dur) var(--ease);
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  cursor: pointer;
}
.ds-btn:hover {
  background: var(--btn-hover);
  text-decoration: none;
}
.ds-btn:active:not(:disabled) {
  background: color-mix(in srgb, var(--btn-bg) 88%, var(--btn-fg));
}
.ds-btn:disabled {
  --btn-bg: var(--surface-2);
  --btn-fg: var(--ink-3);
  --btn-border: var(--line);
  cursor: not-allowed;
}
.ds-btn:focus-visible { outline: 3px solid var(--ink); outline-offset: 2px; box-shadow: 0 0 0 6px var(--accent-soft); }
.ds-btn svg { display: block; flex: none; }
@media (prefers-reduced-motion: reduce) { .ds-btn, .ds-chip { transition-duration: 0.01ms; } }
.ds-btn-primary {
  --btn-bg: var(--accent);
  --btn-fg: var(--accent-ink);
  --btn-border: var(--accent-edge);
  --btn-hover: color-mix(in oklab, var(--accent) 86%, white);
}

