.ds-search {
  position: relative;
  width: 100%;
  max-width: 420px;
}
.ds-search-icon {
  position: absolute;
  top: 50%;
  left: 15px;
  color: var(--ink-2);
  transform: translateY(-50%);
  pointer-events: none;
}
.ds-search-input {
  width: 100%;
  height: 52px;
  padding: 0 48px 0 46px;
  border: 1.5px solid var(--line-strong);
  border-radius: 14px;
  background: var(--surface);
  font-size: 1rem;
  box-shadow: var(--shadow-1);
  appearance: none;
}
.ds-search-input { box-sizing: border-box; color: var(--ink); font-family: var(--font-body); }
.ds-search-input::placeholder {
  color: var(--ink-3);
}
.ds-search-input:focus-visible {
  border-color: var(--ink);
}
.ds-search-input::-webkit-search-cancel-button {
  display: none;
}
.ds-search-kbd {
  position: absolute;
  top: 50%;
  right: 12px;
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 7px;
  color: var(--ink-2);
  font: 650 0.8125rem/1 var(--font-mono);
  transform: translateY(-50%);
  pointer-events: none;
}
.ds-search-input:not(:placeholder-shown) ~ .ds-search-kbd {
  display: none;
}
.ds-search-input:focus-visible { outline: 3px solid var(--ink); outline-offset: 2px; box-shadow: 0 0 0 6px var(--accent-soft); }
@media (hover: none) { .ds-search-kbd { display: none; } }

.ds-nav {
  display: flex;
  gap: 2px;
  margin-left: 4px;
}
.ds-nav { flex-wrap: wrap; font-family: var(--font-body); background: var(--bg); }
.ds-nav-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  padding: 0 10px;
  border-radius: var(--r-control);
  color: var(--ink-2);
  font-size: 0.9375rem;
  font-weight: 600;
  text-decoration: none;
}
.ds-nav-link:hover {
  background: var(--surface-2);
  color: var(--ink);
}
.ds-nav-link.ds-is-active {
  color: var(--ink);
}
.ds-nav-link.ds-is-active::after {
  content: '';
  position: absolute;
  right: 14px;
  bottom: 3px;
  left: 14px;
  height: 3px;
  border-radius: 3px;
  background: var(--accent);
}
.ds-nav-link:focus-visible { outline: 3px solid var(--ink); outline-offset: 2px; box-shadow: 0 0 0 6px var(--accent-soft); }

.ds-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.ds-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 0 16px;
  border: 1px solid var(--line);
  border-radius: var(--r-pill);
  background: var(--surface);
  color: var(--ink);
  font-size: 0.875rem;
  font-weight: 650;
  line-height: 1.2;
  text-decoration: none;
  transition:
    background-color var(--dur) var(--ease),
    border-color var(--dur) var(--ease),
    color var(--dur) var(--ease);
}
.ds-chip { font-family: var(--font-body); cursor: pointer; }
.ds-chip:hover { border-color: var(--line-strong); background: var(--surface-2); }
.ds-chip.ds-is-on {
  border-color: var(--ink);
  background: var(--ink);
  color: var(--bg);
}
.ds-chip:focus-visible { outline: 3px solid var(--ink); outline-offset: 2px; box-shadow: 0 0 0 6px var(--accent-soft); }
@media (prefers-reduced-motion: reduce) { .ds-btn, .ds-chip { transition-duration: 0.01ms; } }

.ds-daily { min-width: 0; padding: 28px; border: 1px solid var(--line-strong); border-radius: var(--r-card); background: var(--surface); }
.ds-daily { color: var(--ink); font-family: var(--font-body); line-height: 1.55; }
.ds-daily-title { font-size: 1.75rem; line-height: 1.2; letter-spacing: -0.03em; }
.ds-daily-title { margin: 0; font-family: var(--font-display); font-weight: 700; }
.ds-daily-meta { max-width: 42ch; margin-top: 10px; color: var(--ink-2); font-size: var(--fs-sm); }
.ds-daily-path { display: flex; align-items: center; margin: 26px 0 14px; isolation: isolate; }
.ds-daily-meta { margin: 10px 0 0; }
.ds-daily-path { padding: 0; list-style: none; }
.ds-daily-node { position: relative; display: grid; place-items: center; flex: 1; min-width: 0; color: var(--ink-2); font-size: 0.75rem; font-variant-numeric: tabular-nums; }
.ds-daily-node > span:first-child { display: grid; place-items: center; width: 24px; height: 24px; border: 1px solid var(--line-strong); border-radius: 50%; background: var(--surface); }
.ds-daily-node:not(:last-child)::after { content: ''; position: absolute; z-index: -1; width: 100%; left: 50%; top: 12px; height: 1px; background: var(--line-strong); }
.ds-daily-node.ds-correct > span:first-child { background: var(--good-soft); border-color: var(--good); color: var(--good); }
.ds-daily-node.ds-partial > span:first-child { background: var(--warn-soft); border-color: var(--warn); color: var(--warn); }
.ds-daily-node.ds-wrong > span:first-child { background: var(--bad-soft); border-color: var(--bad); color: var(--bad); }
.ds-daily-status { color: var(--ink-2); font-size: var(--fs-sm); }
.ds-daily-status { margin: 0; }
.ds-daily-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; margin-top: 22px; }
.ds-sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
